"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[551],{7805:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a new static raycast tree.","params":[],"returns":[{"desc":"","lua_type":"RaycastStatic"}],"function_type":"static","source":{"line":28,"path":"docs/RaycastStatic.lua"}},{"name":"Insert","desc":"Inserts a proxy into the tree. The shape and CFrame are read from the part\\nunless an explicit shape is given. Marks the tree dirty.\\n\\nErrors if `instance` is already inserted.","params":[{"name":"instance","desc":"","lua_type":"BasePart"},{"name":"shape","desc":"Overrides the shape derived from `instance`.","lua_type":"Shape?"},{"name":"cframe","desc":"Overrides `instance.CFrame` as the initial transform.","lua_type":"CFrame?"}],"returns":[],"function_type":"method","source":{"line":40,"path":"docs/RaycastStatic.lua"}},{"name":"Remove","desc":"Removes a proxy from the tree. Marks the tree dirty. No-ops if `instance`\\nwas never inserted.","params":[{"name":"instance","desc":"","lua_type":"Instance"}],"returns":[],"function_type":"method","source":{"line":48,"path":"docs/RaycastStatic.lua"}},{"name":"Build","desc":"Forces a full SAH rebuild now. Calling this is only needed to control\\n*when* the rebuild cost is paid - the first `Raycast()` after any change\\nrebuilds automatically if this was never called.\\n\\n```lua\\nRC:Build() -- e.g. during a loading screen\\n```","params":[],"returns":[],"function_type":"method","source":{"line":59,"path":"docs/RaycastStatic.lua"}},{"name":"Clear","desc":"Removes every proxy and resets internal state.","params":[],"returns":[],"function_type":"method","source":{"line":64,"path":"docs/RaycastStatic.lua"}},{"name":"Raycast","desc":"Returns the nearest hit along the segment `origin -> origin + direction`,\\nor `nil` if nothing was hit. Rebuilds the tree first if it\'s dirty.\\n\\n`direction` is the raw displacement vector, not a unit vector - its\\nmagnitude is the cast distance, matching `workspace:Raycast`.\\n\\nProxies the ray originates inside are ignored, matching native\\n`workspace:Raycast` semantics.","params":[{"name":"origin","desc":"","lua_type":"Vector3"},{"name":"direction","desc":"","lua_type":"Vector3"},{"name":"filter","desc":"Return `false` to exclude a proxy from consideration.","lua_type":"((instance: Instance) -> boolean)?"}],"returns":[{"desc":"","lua_type":"RaycastResult?"}],"function_type":"method","source":{"line":81,"path":"docs/RaycastStatic.lua"}}],"properties":[],"types":[],"name":"RaycastStatic","desc":"Broadphase + narrow-phase raycasting against proxies that don\'t move\\nafter insertion.\\n\\nInsert and remove are cheap - they don\'t refit anything. The tree is\\nmarked dirty on any change and rebuilt lazily, in full, the next time\\n[RaycastStatic:Raycast] is called.\\n\\n```lua\\nlocal Leyr = require(ReplicatedStorage.Leyr)\\n\\nlocal RC = Leyr.RaycastStatic.new()\\nRC:Insert(workspace.Terrain1)\\nRC:Insert(workspace.Terrain2)\\n\\nlocal hit = RC:Raycast(origin, direction) -- rebuilds on first call\\n```","source":{"line":21,"path":"docs/RaycastStatic.lua"}}')}}]);